.slide-root {
  width: 100%;
  height: 100%;
  background:
    radial-gradient(circle at top right, #38bdf833 0%, transparent 28%),
    radial-gradient(circle at bottom left, #f59e0b22 0%, transparent 32%),
    #0b1020;
  color: #e2e8f0;
  overflow: hidden;
}
.slide-root * {
  box-sizing: border-box;
}
.slide-shell {
  position: relative;
  width: 100%;
  height: 100%;
  padding: 68px 72px;
}
.grid-layer {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(148, 163, 184, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(148, 163, 184, 0.08) 1px, transparent 1px);
  background-size: 48px 48px;
  opacity: 0.22;
}
.hero {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1.5fr 0.95fr;
  gap: 28px;
  height: calc(100% - 120px);
}
.hero-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 20px;
}
.eyebrow {
  display: inline-flex;
  align-self: flex-start;
  padding: 8px 14px;
  border-radius: 999px;
  background: #38bdf822;
  border: 1px solid #7dd3fc55;
  color: #7dd3fc;
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.title {
  margin: 0;
  max-width: 880px;
  font-size: 56px;
  line-height: 1.04;
  letter-spacing: 0;
  font-family: Georgia, "Times New Roman", serif;
}
.summary {
  margin: 0;
  max-width: 840px;
  font-size: 26px;
  line-height: 1.42;
  color: #94a3b8;
  white-space: pre-wrap;
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
}
.stat-card, .takeaway-card, .visual-card {
  border-radius: 28px;
  border: 1px solid #7dd3fc30;
  background: rgba(15, 23, 42, 0.92);
  box-shadow: 0 30px 60px rgba(15, 23, 42, 0.35);
  backdrop-filter: blur(10px);
}
.stat-card {
  align-self: center;
  padding: 28px;
}
.visual-card {
  padding: 18px;
  min-height: 420px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.visual-card.visual-card-grid {
  justify-content: stretch;
}
.visual-shell {
  width: 100%;
  height: 100%;
  min-height: 384px;
  border-radius: 22px;
  overflow: hidden;
}
.visual-card.visual-card-grid .visual-shell {
  flex: 1 1 0;
  min-height: 160px;
}
.visual-card.visual-card-grid .visual-shell-1 {
  min-height: 236px;
}
.card-label, .takeaway-label {
  font-size: 18px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #7dd3fc;
  margin-bottom: 14px;
  font-weight: 700;
}
.bullet-list {
  margin: 0;
  padding-left: 26px;
  display: grid;
  gap: 14px;
  font-size: 24px;
  line-height: 1.35;
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
}
.bullet-list li {
  color: #e2e8f0;
}
.bullet-list.compact {
  max-width: 720px;
  gap: 10px;
  font-size: 22px;
}
.footer-row {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1.4fr auto;
  align-items: end;
  gap: 18px;
}
.takeaway-card {
  padding: 24px 28px;
}
.takeaway-text {
  margin: 0;
  font-size: 24px;
  line-height: 1.4;
  color: #e2e8f0;
  white-space: pre-wrap;
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
